import React from 'react';
import CameraScanner from './CameraScanner';
import RiskMeter from './RiskMeter';
import './style.css';

function App() {

  const ingredients = [
    {
      ins: 'INS 102',
      name: 'Tartrazine',
      type: 'Artificial Color',
      risk: 'Moderate Risk',
    },
    {
      ins: 'INS 211',
      name: 'Sodium Benzoate',
      type: 'Preservative',
      risk: 'High Risk',
    }
  ];

  return (
    <div className="app">

      <header className="hero">
        <h1>safe bite</h1>
        <p>
          Scan food ingredients and detect harmful additives instantly.
        </p>
      </header>

      <div className="main-container">

        <div className="left-side">
          <CameraScanner />
        </div>

        <div className="right-side">

          <div className="card">
            <h2>Food Risk Meter</h2>
            <RiskMeter score={50} />
          </div>

          <div className="card">
            <h2>Detected Additives</h2>

            {ingredients.map((item, index) => (
              <div className="ingredient-card" key={index}>

                <div className="ingredient-top">
                  <h3>{item.ins}</h3>

                  <span className="risk-badge">
                    {item.risk}
                  </span>
                </div>

                <p>
                  <strong>Name:</strong> {item.name}
                </p>

                <p>
                  <strong>Type:</strong> {item.type}
                </p>

              </div>
            ))}

          </div>

        </div>

      </div>

    </div>
  );
}

export default App;
